/* @autogenerated */
import { Component, computed, effect, input, OnDestroy, output, Signal, signal } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { Router, RouterModule } from '@angular/router';
import { configValue } from '@shared/context/config/app-config.service';
import { IdentityService } from '@shared/context/identity/identity.service';
import { AppStateService } from '@shared/context/state/app-state.service';
import { MatButtonModule } from '@angular/material/button';
import { MatMenuModule } from '@angular/material/menu';
import { MatIconModule } from '@angular/material/icon';
import { MatListModule } from '@angular/material/list';
import { CommonModule } from '@angular/common';
import { Subscription } from 'rxjs';
import { MenuItem } from 'app/bootstrap/layout/menu-item.model';
import { RouteAccessService } from 'app/bootstrap/layout/menu/route-accessible.service';
import { RuntimeThemeService } from '@shared/context/theme/runtime-theme.service';

@Component({
  selector: 'app-menu',
  standalone: true,
  imports: [CommonModule, RouterModule, MatButtonModule, MatIconModule, MatListModule, MatMenuModule],
  templateUrl: './menu.component.html',
  styleUrl: './menu.component.scss',
  host: { '[class.mini]': "mode() === 'mini'" },
})
export class MenuComponent implements OnDestroy {
  select = output<MenuItem>();
  mode = input<string>('full');
  items = input<MenuItem[] | undefined>();
  title: Signal<string | undefined>;
  logo: Signal<string>;
  productName: Signal<string>;
  currentLanguage: Signal<string>;
  currentTenant: Signal<string>;

  private subscriptions = new Subscription();
  private menuItems = signal<any[]>([]);

  menu = computed(() => this.menuItems());

  public constructor(
    private readonly appstate: AppStateService,
    private readonly router: Router,
    private readonly identity: IdentityService,
    private readonly checker: RouteAccessService,
    theme: RuntimeThemeService,
  ) {
    this.title = configValue('meta.title');
    this.logo = theme.logo;
    this.productName = theme.productName;
    this.currentLanguage = appstate.language;
    this.currentTenant = appstate.tenant;

    const user = appstate.user('main');
    effect((onCleanup) => {
      const items = this.items();
      // Los guards dependen del usuario: al iniciar o cerrar sesión se vuelve a calcular la visibilidad
      user();
      const result = [] as any[];
      const sub = new Subscription();
      if (items) {
        items.forEach((item) => {
          result.push(this.copyItem(item, undefined, sub));
        });
      }
      this.menuItems.set(result);
      onCleanup(() => {
        sub.unsubscribe();
      });
    });
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }

  public run(item: MenuItem, event: any): void {
    this.select.emit(item);
    if (item.route) {
      this.go([item.route]);
    } else {
      alert('No route');
    }
  }

  public go(route: any[]): void {
    const target = [this.currentLanguage(), this.currentTenant(), ...route];
    this.router.navigate(target);
  }

  public idioma(label: string): void {
    this.appstate.language.set(label);
  }

  public tenant(name: string): void {
    this.appstate.tenant.set(name);
  }

  public login(): void {
    this.identity.login('main');
  }

  public logout(): void {
    this.identity.logout('main');
  }

  private childsVisibility(item: any) {
    item.hidden = !item.childs.find((i: any) => !i.hidden);
    item.active = item.childs.find((i: any) => i.active);
  }

  private copyItem(item: MenuItem, parent?: any, sub?: Subscription) {
    const copy = {
      label: item.label,
      icon: item.icon,
      route: item.route,
      hidden: false,
      childs: [],
    } as any;

    if (item.route) {
      copy.active = this.checker.isUrlActive(this.currentLanguage() + '/' + this.currentTenant() + '/' + item.route);
      (sub || this.subscriptions).add(
        this.checker
          .checkRouteGuards(this.currentLanguage() + '/' + this.currentTenant() + '/' + item.route)
          .subscribe((res: any) => {
            copy.hidden = res !== true;
            if (parent) {
              this.childsVisibility(parent);
            }
          }),
      );
      (sub || this.subscriptions).add(
        this.router.events.subscribe((ch) => {
          copy.active = this.checker.isUrlActive(
            this.currentLanguage() + '/' + this.currentTenant() + '/' + item.route,
          );
          if (parent) {
            this.childsVisibility(parent);
          }
        }),
      );
    }
    if (item.subItems) {
      item.subItems.forEach((sitem) => {
        copy.childs.push(this.copyItem(sitem, copy, sub));
      });
    }
    if (!item.route) {
      this.childsVisibility(copy);
    }
    return copy;
  }
}
